MultiLanguageSpellData['de'][90853] = {name = "[q0]Fußkette mit goldenen Glöckchen", additional_info = "Wirken in 2 sek. 5\n[q]Dieses schlanke Kettchen aus purpurnem Metall ist mit siebzehn kleinen Glöckchen und etwas größeren, braunen Glasperlen geschmückt. Möglicherweise trug es einst eine Tänzerin oder eine junge Dame der Gesellschaft.\n[q0]Fußkette mit goldenen Glöckchen\nWird beim Aufheben gebunden"}
MultiLanguageSpellData['de'][90854] = {name = "Visionär", additional_info = "Sofort\n[q]Erhöht die Zaubermacht 15 Sek. lang um 8 . bis zu 6-mal stapelbar."}
