MultiLanguageSpellData['de'][90949] = {name = "Verschlingende Flammen", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Verursacht an allen Feinden vor Valiona 11344653 Schattenschaden. Verschlingende Flammen verursachen weniger Schaden je weiter der Gegner von Valiona entfernt ist."}
MultiLanguageSpellData['de'][90950] = {name = "Verschlingende Flammen", additional_info = "Unbegrenzte Reichweite\nWirken in 2.5 sek.\n[q]'Verschlingende Flammen' verursacht alle 1 Sek. 11344653 Schattenschaden. Der Schaden lässt nach, je weiter das Ziel vom Ursprung der verschlingenden Flammen entfernt ist."}
