MultiLanguageSpellData['de'][90960] = {name = "Wirbelnde Klingen", additional_info = "{40 Energie} {35 Meter Reichweite}\nSofort\nBenötigt Waffen\n[q]Umgibt den Feind mit wirbelnden Klingen. Fügt allen in der Nähe befindlichen Einheiten körperlichen Schaden zu."}
