MultiLanguageSpellData['de'][90994] = {name = "Tunnel", additional_info = "40 Meter Reichweite\nWirken in 1 sek.\n[q]Gräbt sich unter dem Zaubernden in die Erde, wodurch er bis Abbruch lang verschwindet."}
MultiLanguageSpellData['de'][90996] = {name = "Crescendo des Leidens", additional_info = "Sofort\n[q]Erhöht die Zaubermacht 10 Sek. lang um 226 ."}
MultiLanguageSpellData['de'][90997] = {name = "[q4]Bartaxt aus Niffelvar", additional_info = "Wirken in 2 sek. 15\n[q]Viele von den Vrykul gefertigte Äxte haben einen ungewöhnlichen Stil: Der Klingenbart streckt sich sehr weit über das Maß des Axtkopfes hinaus. Durch diese Bauweise, die sowohl für Werkzeuge als auch Waffen vewendet wird, erhöht sich die Schnittfläche, während das Gewicht minimiert wird. Einige zwergische Äxte weisen eine ähnliche Konstruktionsweise auf.\n[q4]Bartaxt aus Niffelvar\n[q7]Wird an Kriegsmeute gebunden\nEinhändig Axt\n3 - 8 Schaden Geschwindigkeit 2.60\n(2.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 1.\nHaltbarkeit 110 / 110\n27"}
MultiLanguageSpellData['de'][90998] = {name = "Gesang der Trauer", additional_info = "[q]Wenn Eure Zauber einem Ziel Schaden zufügen, das über weniger als 35% Gesundheit verfügt, wird Eure Zaubermacht 10 Sek. lang um 226 erhöht. Nachdem der Effekt endet, kann er 10 Sek. lang nicht erneut ausgelöst werden.\n(20s Abklingzeit)"}
