MultiLanguageSpellData['de'][91008] = {name = "[q0]Skramasax", additional_info = "Wirken in 2 sek. 5\n[q]Ein Skramasax ist eine lange, gerade und einschneidige Klinge mit einem simplen Griff, die von vielen Vrykulkriegern als Zweitwaffe getragen wird. Ein weitverbreiteter Kampfstil von Kriegern gibt eine Axt in der Haupthand und ein Skramasax in der Schildhand vor.\n[q0]Skramasax\nWird beim Aufheben gebunden"}
MultiLanguageSpellData['de'][91009] = {name = "Renegatenstärke", additional_info = "Sofort\n[q]Erfüllt das Ziel mit der Stärke der Defias. Erhöht verursachten körperlichen Schaden um 200%, reduziert erlittenen Schaden von Zaubern und Fähigkeiten mit Flächenwirkung um 90% und erhöht die Gesundheit um 300%."}
MultiLanguageSpellData['de'][91011] = {name = "Item - Proc Spell Power On Dmg", additional_info = "[q]Eure offensiven Zauber haben eine Chance, Eure Zaubermacht 20 Sek. lang um 226 zu erhöhen.\n(Procchance: 20%, 1.667Min. Abklingzeit)"}
MultiLanguageSpellData['de'][91012] = {name = "[q0]Zündzeug", additional_info = "Wirken in 2 sek. 5\n[q]Dieses einfache Paar von Feuerstein und Stahl wurde zum Feuerschlagen genutzt. Die Halterung des Stabes ist wie ein Drachenkopf geformt, die flache Metallklinge zeigt ein stilisiertes Fischmotiv.\n[q0]Zündzeug\nWird beim Aufheben gebunden"}
MultiLanguageSpellData['de'][91013] = {name = "Zeitwurzel", additional_info = "Sofort\n[q]Erhöht Eure Zaubermacht 15 Sek. lang um 1926."}
MultiLanguageSpellData['de'][91014] = {name = "[q0]Zahnbesetzte Umhangfibel", additional_info = "Wirken in 2 sek. 5\n[q]Diese Gewandschließe diente einst dazu, den schweren Umhang eines Vrykul um die Schultern zu befestigen. An dem kreuzförmigen Bügel sind zwei große, jedoch abgestumpfte Zähne angebracht. Sie stammen wahrscheinlich von einem gealterten Protodrachen. Es ist unklar, ob der Besitzer eine Zuneigung zu dem alten Drachen hatte oder ob die Kreatur die einzige war, die er bezwingen konnte.\n[q0]Zahnbesetzte Umhangfibel\nWird beim Aufheben gebunden"}
