MultiLanguageSpellData['de'][91788] = {name = "Kanonenkugel", additional_info = "70 Meter Reichweite\nWirken in 1 sek.\n[q]Feuert eine Kanonenkugel auf den Gegner ab, verursacht schweren Schaden und betäubt ihn."}
MultiLanguageSpellData['de'][91790] = {name = "Kanope", additional_info = "Wirken in 2 sek. 5\n[q]Dieses Gefäß enthält die versteinerten inneren Organe von Imperator Ninjter. Offenbar starb er nur wenige Jahre, nachdem er seine vom Volk voller Hoffnung erwartete Herrschaft antrat.\nWird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>"}
