MultiLanguageSpellData['de'][93326] = {name = "Sandsteindrache", additional_info = "Wirken in 1.5 sek.\n[q]Verwandelt Euch in einen Sandsteindrachen, wodurch Ihr sehr schnell fliegen und einen Verbündeten auf dem Rücken tragen könnt. Das ist ein Flugreittier.\n[q]\"Sandsteindrachen wurden vor langer Zeit ausgiebig vom berühmten Alchemisten Zander Flinkspross untersucht. Es wird sogar behauptet, dass Zander Tränke entwickelt hat, welche es ermöglichen, die Physiologie dieser Drachen nachzuahmen.\"\nBeruf:\nAlchemie"}
MultiLanguageSpellData['de'][93327] = {name = "Erdbestattung", additional_info = "20 Meter Reichweite\nSofort\n[q]Erdrückt den Feind in einer irdenen Umklammerung und verursacht 30 Sek. lang alle 2 Sek. 341 Schaden. Zusätzliche Anwendungen erhöhen zwar den Schmerz, doch starke Winde können dem Effekt entgegenwirken."}
MultiLanguageSpellData['de'][93328] = {name = "[q4]Phiole der Sande", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nPyriumbeschichtete Kristallphiole , Sande der Zeit (8), Echtgold (12), Fläschchen der Winde (8), Fläschchen der Titanenstärke (8), Tiefsteinöl (8)\nBeruf:\nArchäologie\nBeute von:\nKanope\n\n\n[q4]Phiole der Sande\nReittier[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, Euch in einen Drachen zu verwandeln, wodurch Ihr einen Verbündeten auf dem Rücken tragen könnt. Das ist ein Flugreittier.\n[q2]Verwandelt Euch in einen Sandsteindrachen, wodurch Ihr sehr schnell fliegen und einen Verbündeten auf dem Rücken tragen könnt. Das ist ein Flugreittier.\n1 - 80 ( 80)\nBenötigtUnerfahrenes Reiten\n[q]\"Sandsteindrachen wurden vor langer Zeit ausgiebig vom berühmten Alchemisten Zander Flinkspross untersucht. Es wird sogar behauptet, dass Zander Tränke entwickelt hat, welche es ermöglichen, die Physiologie dieser Drachen nachzuahmen.\"\nBeruf:\nAlchemie"}
