MultiLanguageSpellData['de'][98533] = {name = "[q4]Panzer einer ausgestorbenen Schildkröte", additional_info = "Wirken in 2 sek. 15\n[q]Schildkröten sind uralte Kreaturen, die sich Laufe der Äonen kaum verändert haben. Es gibt drei Hauptkategorien: Meeresschildkröten, Landschildkröten und Süßwasserschildkröten. Dieser Panzer ist wahrscheinlich der einer Landschildkröte, obwohl er fast undurchdringlich ist, und würde einen großartigen wenn auch etwas albernen Schild abgeben.\n[q4]Panzer einer ausgestorbenen Schildkröte\n[q7]Wird an Kriegsmeute gebunden\nSchildhand Schild\n46 Rüstung\n+2 Stärke\n+6 Intelligenz\n+3 Ausdauer\n[q2]+ 2 Ausweichen\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 120 / 120\n32"}
MultiLanguageSpellData['de'][98534] = {name = "Meteorbrand", additional_info = "40 Meter Reichweite\nSofort\n[q]Rauch steigt aus dem verkohlten Krater auf, den ein Meteoreinschlag verursacht hat."}
MultiLanguageSpellData['de'][98535] = {name = "Springende Flammen", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Fandral springt auf ein Ziel zu und hinterlässt einen Geist der Flamme, der 1 Min. lang bestehen bleibt. Er landet in flammender Pracht, die den Boden seines Zielortes entfacht und gegnerischen Einheiten alle 0.5 Sek. 0 Feuerschaden zufügt."}
