MultiLanguageSpellData['de'][108280] = {name = "Totem der Heilungsflut", additional_info = "1.12% von Grundmana\nSofort 3 min Abklingzeit\n[q]Beschwört ein Totem zu Euren Füßen, das 10 Sek. lang bestehen bleibt. Das Totem pulsiert alle 2 Sek. und heilt dabei alle Gruppen- oder Schlachtzugsmitglieder innerhalb von 40 Metern um (350% der Zaubermacht) Gesundheit.\n\n Verringerte Heilung über 5 Ziele hinaus."}
MultiLanguageSpellData['de'][108281] = {name = "Führung der Ahnen", additional_info = "Sofort 2 min Abklingzeit\n[q]Wiederherstellung\n Für die nächsten 10 Sek. werden bis zu 3 verletzte Gruppen- oder Schlachtzugsmitglieder in der Nähe um 10% Eurer hervorgerufenen Heilung und 25% Eures verursachten Schadens geheilt, um bis zu (Gesamtgesundheit * 20 / 100) Gesundheit pro Sekunde und Ziel.\n\nElementar\n Für die nächsten 10 Sek. werden bis zu 3 verletzte Gruppen- oder Schlachtzugsmitglieder in der Nähe um 25% Eurer hervorgerufenen Heilung und 25% Eures verursachten Schadens geheilt, um bis zu (Gesamtgesundheit * 20 / 100) Gesundheit pro Sekunde und Ziel."}
MultiLanguageSpellData['de'][108283] = {name = "Echo der Elemente", additional_info = "[q]'Springflut', 'Lavaeruption' und das Totem des heilenden Flusses haben 2 Aufladungen. Effekte, die die verbleibende Abklingzeit dieser Fähigkeiten abschließen, erzeugen stattdessen 1 Aufladung."}
MultiLanguageSpellData['de'][108284] = {name = "Beständige Totems", additional_info = "[q]Beim Beschwören eines zweiten Totems desselben Elements wird das erste Totem nicht mehr entfernt. Es kann immer nur ein zusätzliches Totem bestehen. Wirkt sich nicht auf Feuertotems aus."}
