MultiLanguageSpellData['de'][113996] = {name = "Knochenrüstung", additional_info = "Sofort\n[q]Umgibt den Zaubernden mit einer Knochenrüstung, die einen einzelnen knochenbasierten Angriff absorbiert."}
MultiLanguageSpellData['de'][113998] = {name = "Geheul der Verzweiflung", additional_info = "Kanalisiert (Wirken in 10 sek.)\n[q]Ruft niedere Sha herbei. Beschwört 10 Sek. lang alle 2 Sek. eins."}
MultiLanguageSpellData['de'][113999] = {name = "Knochenstachel", additional_info = "100 Meter Reichweite\nWirken in 1 sek.\n[q]Schlägt mit einem Knochenstachel nach dem Ziel und fügt ihm 4739 körperlichen Schaden zu."}
MultiLanguageSpellData['de'][114000] = {name = "Elektroschock", additional_info = "100 Meter Reichweite\nSofort\n[q]Fügt dem Ziel 1896 Naturschaden zu und betäubt es 3 Sek. lang."}
MultiLanguageSpellData['de'][114001] = {name = "Teleportieren", additional_info = nil}
MultiLanguageSpellData['de'][114004] = {name = "Durchstechender Wurf", additional_info = "100 Meter Reichweite\nKanalisiert (Wirken in 2 sek.)\n[q]Hundemeister Braun wirft eins seiner Messer auf einen beliebigen Gegner, fügt dadurch allen in der Flugbahn befindlichen Gegnern 1658 körperlichen Schaden zu und wirkt auf die Ziele 'Blutige Sauerei'."}
MultiLanguageSpellData['de'][114006] = {name = "Dröhnendes Gebrüll", additional_info = "Nahkampfreichweite\n{Sofort} {5 sek. Abklingzeit}\n[q]Verringert 10 Sek. lang die Rüstung von Gegnern in der Nähe."}
MultiLanguageSpellData['de'][114007] = {name = "Seelenflamme", additional_info = "Sofort\n[q]Erschafft einen Teich aus ätzenden Tränen, der Naturschaden verursacht und mit der Zeit wächst."}
MultiLanguageSpellData['de'][114009] = {name = "Seelenflamme", additional_info = "Sofort\n[q]Eine leuchtende Seelenflamme fügt nahen Gegnern 41 Feuerschaden zu. Die Flamme wächst mit der Zeit."}
MultiLanguageSpellData['de'][114011] = {name = "Rüstungshieb", additional_info = "Nahkampfreichweite\nSofort\n[q]Der Hieb verursacht 150% Waffenschaden und erhöht den erlittenen körperlichen Schaden 10 Sek. lang um 20%. Stapelbar."}
MultiLanguageSpellData['de'][114014] = {name = "Shurikenwurf", additional_info = "{40 Energie} {30 Meter Reichweite}\nSofort\n[q]Wirft einen Shuriken auf ein gegnerisches Ziel, der [(23.7838% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] körperlichen Schaden verursacht.\n\nGewährt 1 Combopunkt."}
MultiLanguageSpellData['de'][114015] = {name = "Erwartung", additional_info = "[q]Ihr könnt über bis zu 10 Combopunkt verfügen. Finishing-Moves zehren trotzdem maximal 5 Combopunkte auf."}
MultiLanguageSpellData['de'][114016] = {name = "Auf die Hörner nehmen", additional_info = "8 - 30 Meter Reichweite\n{Wirken in} {1 sek. 5 sek. Abklingzeit}\n[q]Bei diesem Vorstoß auf den aktuellen Standort des Gegners wird die Bewegungsgeschwindigkeit 3 Sek. lang um 60% erhöht. Bei Ankunft am Ziel werden alle Gegner in der Nähe zurückgestoßen."}
MultiLanguageSpellData['de'][114017] = {name = "Durchstechender Wurf", additional_info = nil}
MultiLanguageSpellData['de'][114018] = {name = "Verhüllender Nebel", additional_info = "Sofort 6 min Abklingzeit\nBenötigt Verstohlenheit\n[q]Breitet einen Schleier aus, der Gruppen- und Schlachtzugsmitglieder innerhalb von 30 Metern in Schatten hüllt und 15 Sek. lang tarnt."}
MultiLanguageSpellData['de'][114019] = {name = "Auf die Hörner nehmen", additional_info = "30 Meter Reichweite\n{Sofort} {3 sek. Abklingzeit}\n[q]Schleudert ein gegnerisches Ziel hoch in die Luft."}
