MultiLanguageSpellData['de'][114030] = {name = "Wachsamkeit", additional_info = "40 Meter Reichweite\nSofort 2 min Abklingzeit\n[q]Beschützt 12 Sek. lang einen Verbündeten und verringert so seinen erlittenen Schaden um 30% und gestattet Euch den Einsatz von 'Spott', ohne Abklingzeit auszulösen."}
