MultiLanguageSpellData['de'][121817] = {name = "Kämpferische Weisheit", additional_info = "[q]Außerhalb des Kampfs pendelt sich Euer Chi auf 2 ein, anstatt erschöpft zu werden.\n\n Alle 15 Sek. setzt Euer nächster Einsatz von 'Tigerklaue' zusätzlich 'Schadensumleitung' ein und verursacht 30% mehr Schaden.\n\n Schadensumleitung\nNebelwirker ( Nebelwirkermönch )\n Stößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 25% des geheilten Werts als Naturschaden zufügt.\n\n Braumeister, Windläufer\n Stößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 10% des geheilten Werts als Naturschaden zufügt. [ Schadensumleitung : Entzieht all Euren heilenden Sphären positives Chi, um die Heilung durch 'Schadensumleitung' zu erhöhen ] [ Schadensumkehr : Erzeugt [(120% der Zaubermacht) + 30] Chi. ]"}
MultiLanguageSpellData['de'][121818] = {name = "Stampede", additional_info = "40 Meter Reichweite\nSofort 5 min Abklingzeit\n[q]Beschwört alle Eure Begleiter, die daraufhin Euer aktuelles Ziel 40 Sek. lang angreifen. Auf diese Weise herbeigerufene Begleiter verursachen in Arenen und auf Schlachtfeldern nur 25% ihres normalen Schadens."}
MultiLanguageSpellData['de'][121820] = {name = "Obsidiannachtschwinge", additional_info = "Wirken in 1.5 sek.\n[q]Verwandelt Euch in eine Obsidiannachtschwinge, wodurch Ihr sehr schnell fliegen und einen Verbündeten auf Eurem Rücken tragen könnt. Das ist ein Flugreittier.\n[q]\"Wenn man nicht mehr rennen kann, kriecht man halt, und wenn man nicht mehr kriechen kann, sucht man sich jemanden, der einen trägt.\"\nWerbt einen Freund"}
