MultiLanguageSpellData['de'][121836] = {name = "Saphirpanther", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren Saphirpanther oder gibt ihn wieder frei.\n[q]\"Legenden zufolge hat ein uralter pandarischer Kaiser den ersten juwelenbesetzten Panther für seinen Sohn gefertigt, nachdem dessen Zwillingsbruder einer Krankheit erlag.\"\nBeruf:\nJuwelierskunst"}
