MultiLanguageSpellData['de'][122708] = {name = "Großes Expeditionsyak", additional_info = "Wirken in 1.5 sek.\n[q]Ruft ein großes Expeditionsyak herbei, komplett mit Grummel-Begleitern für all Eure Geschäftsbedürfnisse!\n[q]\"Diese Lasttiere sind dafür bekannt, dass sie mehr als das Fünffache ihres Gewichtes tragen und mehrere Tage ohne Nahrung oder Wasser auskommen können.\"\nVerkäufer:\nOnkel Dickehose\nZone:\nKun-Lai-Gipfel\nKosten:\n120000"}
