MultiLanguageSpellData['de'][127124] = {name = "Pulverfass des Schlossermeisters", additional_info = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nEinfaches Holz , Hochexplosives Schwarzpulver\nBerufsausbilder:\nIngenieurskunst von Pandaria (1)\nKosten:\n10\n\n[q2]Benutzen: Sprengt verschlossene Türen und Kisten auf, die eine Fertigkeit von bis zu 35 im Schlossknacken benötigen.\nBenötigtIngenieurskunst von Pandaria\n(1)"}
MultiLanguageSpellData['de'][127127] = {name = "G91-Landhai", additional_info = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbolzen (2), Hochexplosives Schwarzpulver (2)\nBerufsausbilder:\nIngenieurskunst von Pandaria (1)\nKosten:\n10\n\n(3)\n[q2]Benutzen: Fügt einem Gegner in bis zu 45 Metern Entfernung und Gegnern innerhalb von 10 Metern um das Primärziel 688 Feuerschaden zu. (1 Min Abklingzeit)\n32"}
MultiLanguageSpellData['de'][127128] = {name = "Goblindrachengewehr - Nr. II", additional_info = "Wirken in 3 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbolzen (3), Hochexplosives Schwarzpulver (8)\nBerufsausbilder:\nIngenieurskunst von Pandaria (25)\nKosten:\n1\n\n[q2]Benutzen: Entfesselt eine Blitzentladung, die Zielen in einem 10 Meter großen kegelförmigen Bereich vor dem Wirkenden 4 Sek. lang alle 0.5 Sek. 48 Naturschaden zufügt.\n\n Kann während der Bewegung gewirkt werden. (30 Sek. Abklingzeit)\n50 Aufladungen\n32"}
MultiLanguageSpellData['de'][127129] = {name = "[q4]Blingtron 4000", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nLebendiger Stahl (4), Trilliumbarren (4), Geistereisenbarren (4), Aragonit (4), Dioptas (4), Geist der Harmonie (4)\nBerufsausbilder:\nIngenieurskunst von Pandaria (75)\nKosten:\n3\n50\n\n[q4]Blingtron 4000\nWird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Setzt den unglaublichen Blingtron 4000 zusammen, einen Roboter von unendlichem Reichtum. Bling, wie er gerne genannt wird, händigt jedem, der mit ihm spricht, ein zufälliges Geschenk aus, aber nur ein Mal pro Tag. Hält 10 Min. lang an. (4 Std. Abklingzeit)\nBenötigtIngenieurskunst von Pandaria\n(75)"}
MultiLanguageSpellData['de'][127130] = {name = "[q2]Nebeldurchdringende Brille", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbolzen (8), Geist der Harmonie (2)\nBerufsausbilder:\nIngenieurskunst von Pandaria (1)\nKosten:\n10\n\n[q2]Nebeldurchdringende Brille\nWird beim Anlegen gebunden\nKopf\n[q2]Anlegen: Ermöglicht Euch, zusätzliche Erzadern und Kräutervorkommen aufzuspüren, während Ihr Euch in Pandaria befindet.\n[q]\"Obwohl diese Brille sehr modisch ist, muss sie nicht aufgesetzt werden, um von ihrer Spezialfähigkeit zu profitieren.\""}
MultiLanguageSpellData['de'][127131] = {name = "Thermischer Amboss", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nHochexplosives Schwarzpulver (8), Geistereisenbolzen (6)\nBerufsausbilder:\nIngenieurskunst von Pandaria (25)\nKosten:\n1\n\n[q2]Benutzen: Platziert einen thermischen Amboss zu Euren Füßen, der allen in der Nähe befindlichen Charakteren erlaubt, sowohl einen Amboss als auch eine Schmiede zu benutzen. Hält 5 Min. lang an. (5 Min Abklingzeit)\n20 Aufladungen"}
MultiLanguageSpellData['de'][127132] = {name = "[q3]Wurmlochgenerator: Pandaria", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nTrilliumbarren (12), Geist der Harmonie (2)\nBerufsausbilder:\nIngenieurskunst von Pandaria (45)\nKosten:\n1\n75\n\n[q3]Wurmlochgenerator: Pandaria\nWird bei Benutzung gebunden\nSpielzeug\n[q2]Benutzen: Teleportiert Euch an irgendeinen Ort in Pandaria. Der exakte Ort ist schwer zu bestimmen, aber er ist wahrscheinlich ziemlich weit entfernt. (15 Min Abklingzeit)\n29\nBenötigtIngenieurskunst von Pandaria\n(1)\n[q]\"An der Seite ist eine winzige Notiz: Huiiiiiiiiiiiiiii!\""}
MultiLanguageSpellData['de'][127134] = {name = "[q3]Geistereisendrachling", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWindwollstoff (12), Geistereisenbolzen (8), Hochexplosives Schwarzpulver (4)\nOptionale Reagenzien:\n[] (#49)\nBerufsausbilder:\nIngenieurskunst von Pandaria (25)\nKosten:\n1\n\n[q3]Geistereisendrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n[q0]Zahnradsockel\n[q0]Zahnradsockel\n[q0]Zahnradsockel\n\n[q2]Anlegen: Eure Angriffe haben eine Chance, einen Geistereisendrachling zu beschwören, der 20 Sek. lang an Eurer Seite kämpft. (Procchance: 25%, 1Min. Abklingzeit)\n33"}
MultiLanguageSpellData['de'][127135] = {name = "[q3]Mechanischer Pandarendrachling", additional_info = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbarren (4), Trilliumbarren (6), Geist der Harmonie (2)\nBerufsausbilder:\nIngenieurskunst von Pandaria (50)\nKosten:\n2\n\n[q3]Mechanischer Pandarendrachling\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euren Welpling beschwören oder wieder freigeben.\n1 - 80 ( 80)"}
MultiLanguageSpellData['de'][127136] = {name = "[q3]Großwildjäger", additional_info = "Wirken in 3 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbolzen (12), Haarfeiner Sprengstoffauslöser , Schäftung aus Walnussholz , Verspiegeltes Zielfernrohr\nOptionale Reagenzien:\n[] (#49)\nBerufsausbilder:\nIngenieurskunst von Pandaria (1)\nKosten:\n10\n\n[q3]Großwildjäger\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n6 - 12 Schaden Geschwindigkeit 3.00\n(3.0 Schaden pro Sekunde)\n+3 Beweglichkeit\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 2.\n\n[q0]Prismatischer Sockel\n[q0]Sockelbonus: + 1 Beweglichkeit\n\nHaltbarkeit 100 / 100\n32"}
MultiLanguageSpellData['de'][127137] = {name = "[q3]Trilliumlangstreckenpräzisionsgewehr", additional_info = "Wirken in 3 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nTrilliumbarren (12), Haarfeiner Sprengstoffauslöser , Geist der Harmonie , Fürst von Schmetternichs Todeszielfernrohr\nBerufsausbilder:\nIngenieurskunst von Pandaria (40)\nKosten:\n1\n50\n\n[q3]Trilliumlangstreckenpräzisionsgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n6 - 12 Schaden Geschwindigkeit 3.00\n(3.0 Schaden pro Sekunde)\n+3 Beweglichkeit\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 4.\n\n[q0]Prismatischer Sockel\n[q0]Sockelbonus: + 0 Beweglichkeit\n\nHaltbarkeit 100 / 100\n35"}
MultiLanguageSpellData['de'][127138] = {name = "[q3]Rakete mit abgereichertem Kyparium", additional_info = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nLebendiger Stahl (12), Kyparit (200), Kugel der Geheimnisse (3), Hochexplosives Schwarzpulver (12), Geist der Harmonie (12), Geistereisenbolzen (20)\nBerufsausbilder:\nIngenieurskunst von Pandaria (75)\nKosten:\n3\n50\n\n[q3]Rakete mit abgereichertem Kyparium\nEinzigartig\nReittier[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Eine Höhepunkt goblinischer Ingenieurskunst! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n1 - 80 ( 80)\nBenötigtUnerfahrenes Reiten\n\n\n[q]\"Wenn Kyparit seine Bernsteinessenz entzogen wird, kommt es kaum noch zu Korrosion durch Raketentreibstoff.\"\nBeruf:\nIngenieurskunst"}
MultiLanguageSpellData['de'][127139] = {name = "[q3]Geosynchroner Weltendreher", additional_info = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nLebendiger Stahl (12), Trilliumbarren (12), Geist der Harmonie (12), Geistereisenbolzen (20), Kugel der Geheimnisse (3)\nBerufsausbilder:\nIngenieurskunst von Pandaria (75)\nKosten:\n3\n50\n\n[q3]Geosynchroner Weltendreher\nEinzigartig\nReittier[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Eine Apparatur, die die Welt selbst unter Euch rotieren lässt! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n1 - 80 ( 80)\nBenötigtUnerfahrenes Reiten\n\n\n[q]\"Diese Rakete wurde ursprünglich entworfen, um die Umdrehung der Welt zu beschleunigen und so die Nächte zu verkürzen. Wenn Gnome unter Schlafmangel leiden, setzen sie sich große Ziele.\"\nBeruf:\nIngenieurskunst"}
