MultiLanguageSpellData['de'][127154] = {name = "Onyxwolkenschlange", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört eine reitbare Onyxwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n[q]\"Onyxwolkenschlangen sind aggressiver und waghalsiger als ihre Verwandten, die himmlischen Onyxwolkenschlangen.\"\nQuest:\nÜberraschungsangriff!\nOrt:\nTonlongsteppe"}
MultiLanguageSpellData['de'][127156] = {name = "Purpurwolkenschlange", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört eine reitbare Purpurwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n[q]\"Purpurwolkenschlangen neigen zu Träumereien und begeben sich spontan auf scheinbar zufällige Reisen, die gelegentlich Tage andauern.\"\nErfolg:\nHeldenruhm von Pandaria\nKategorie:\nDungeons & Schlachtzüge"}
