MultiLanguageSpellData['de'][127161] = {name = "Himmlische Purpurwolkenschlange", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört eine reitbare himmlische Purpurwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n[q]\"Himmlische Purpurwolkenschlangen zählen zu den edelsten Drachen.\"\nErfolg:\nRuhm des Pandaria-Schlachtzüglers\nKategorie:\nDungeons & Schlachtzüge"}
MultiLanguageSpellData['de'][127163] = {name = "Kugel der Macht", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Ihr tragt die Kugel der Macht.\n Das Tragen der Kugel verschafft Eurem Team Siegpunkte.\n Verringert die erhaltene Heilung um 0%."}
MultiLanguageSpellData['de'][127164] = {name = "Himmlische Goldwolkenschlange", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört eine reitbare himmlische Goldwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n[q]\"Dieser großen Kreatur, die glüht wie ein Sonnenaufgang über den Bergen, entspringt Wärme und Hoffnung.\"\nVerkäufer:\nNebelwirker Ku\nZone:\nZeitlose Insel\nKaiser Shaohao - Ehrfürchtig"}
MultiLanguageSpellData['de'][127165] = {name = "Yu'lei, Tochter der Jade", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Yu'lei, Tochter der Jade, und gibt sie wieder frei. Das ist ein Flugreittier.\n[q]\"Dieser großen Kreatur, die wie Mondlicht durch feinste Jade schimmert, entspringt Wärme und Weisheit.\"\nVerkäufer:\nNebelwirkerin Xia\nZone:\nZeitlose Insel\nKosten:\n5.000"}
MultiLanguageSpellData['de'][127169] = {name = "Himmlische Azurwolkenschlange", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört eine reitbare himmlische Azurwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n[q]\"Dieser großen Kreatur, die wie ein wolkenloser Himmel an einem Sommerabend leuchtet, entspringt Wärme und Gelassenheit.\"\nErfolg:\nHerr der Reittiere\nKategorie:\nReittiere"}
MultiLanguageSpellData['de'][127170] = {name = "Astrale Wolkenschlange", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört eine reitbare astrale Wolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n[q]\"Man geht davon aus, dass die astralen Wolkenschlangen Antworten auf einige der größten Geheimnisse des Lebens kennen. Zu dumm, dass sie nicht sprechen können.\"\nBeute von:\nBehälter aus reiner Energie"}
MultiLanguageSpellData['de'][127171] = {name = "Heimtückisches Zerfleischen", additional_info = "Nahkampfreichweite\n{Sofort} {5 sek. Abklingzeit}\n[q]Greift einen Gegner brutal an und fügt ihm 9 Sek. lang alle 1 Sek. körperlichen Schaden zu."}
