MultiLanguageSpellData['de'][127176] = {name = "Goldener Reitkranich", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren goldenen Reitkranich und gibt ihn wieder frei.\n[q]\"Der Kranich ist das Symbol von Weisheit und Edelmut. Seine Fähigkeit, uns in die Lüfte zu tragen, ist nichts weniger als ein Wunder. - Jaluu der Spendable\"\nVerkäufer:\nJaluu der Spendable\nZone:\nTal der Ewigen Blüten\nGoldener Lotus - Ehrfürchtig\nKosten:\n2500"}
MultiLanguageSpellData['de'][127177] = {name = "Königlicher Reitkranich", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren königlichen Reitkranich und gibt ihn wieder frei.\n[q]\"Der Kranich ist das Symbol von Weisheit und Edelmut. Seine Fähigkeit, uns in die Lüfte zu tragen, ist nichts weniger als ein Wunder. - Jaluu der Spendable\"\nVerkäufer:\nJaluu der Spendable\nZone:\nTal der Ewigen Blüten\nGoldener Lotus - Ehrfürchtig\nKosten:\n1500"}
MultiLanguageSpellData['de'][127178] = {name = "Dschungelreitkranich", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren Dschungelreitkranich und gibt ihn wieder frei.\n[q]\"Als geschätztes Reittier ist der Dschungelkranich im Süden Pandarias für seine Geschwindigkeit und Beweglichkeit bekannt, die das Leben auf der Flucht vor den Krasaritigern mit sich bringt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
