MultiLanguageSpellData['de'][127209] = {name = "Schwarzes Reityak", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört ein reitbares schwarzes Reityak oder gibt es wieder frei.\n[q]\"Grummel, die nachts zum Kun-Lai-Gipfel reisen, bevorzugen diese dunkelhaarigen Yaks, damit sie nicht gesehen werden. Allerdings entfernen sie dazu erst einmal die Glocken aus deren Schmuck.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][127213] = {name = "Bescheidenes Expeditionsyak", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört ein reitbares braunes Reityak oder gibt es wieder frei.\n[q]\"Anders als seine lastentragenden Artgenossen reist dieses Yak gerne leicht und auch keine allzu langen Strecken am Stück.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
