MultiLanguageSpellData['de'][136163] = {name = "Großer Greif", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren großen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Die ausgezeichnete Sehkraft der Greifen ermöglicht es ihnen, in die Ferne zu blicken und ihre Reiter vor bevorstehenden Gefahren zu warnen.\"\nQuest:\nDie Stille\nZone:\nKun-Lai-Gipfel"}
MultiLanguageSpellData['de'][136164] = {name = "Großer Wyvern", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren großen Wyvern oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Wyvern kommen aus einigen der lebensfeindlichsten Gebiete von Kalimdor, weshalb sie meisterhaft darin sind, sich an eine beliebige Umgebung zu gewöhnen.\"\nQuest:\nAtem der dunkelsten Schatten\nZone:\nKun-Lai-Gipfel"}
