MultiLanguageSpellData['de'][138641] = {name = "Roter Urraptor", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren roten Urraptor und gibt ihn wieder frei.\n[q]\"Raptoren haben sich in praktisch allen Landen von Azeroth verbreitet. Es ist unklar, ob die Trolle sie hergeführt haben oder sie ihnen gefolgt sind.\"\nBeute von:\nZerbrochene Ureischale"}
MultiLanguageSpellData['de'][138642] = {name = "Schwarzer Urraptor", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren schwarzen Urraptor und gibt ihn wieder frei.\n[q]\"Geschwindigkeit, Gerissenheit und Wildheit sind Dinge, die Trolle und Raptoren aneinander bewundern.\"\nBeute von:\nZerbrochene Ureischale"}
MultiLanguageSpellData['de'][138643] = {name = "Grüner Urraptor", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren grünen Urraptor und gibt ihn wieder frei.\n[q]\"Raptoren sind genauso treu, wie sie bösartig sind. Wenn Ihr kein Freund seid, seid Ihr eine Mahlzeit.\" - Kijara\nBeute von:\nZerbrochene Ureischale"}
