MultiLanguageSpellData['de'][138876] = {name = "[q3]Die wiedergeborene Planaraxt", additional_info = "Wirken in 2.5 sek.\nTools: Schmiedehammer\nReagenzien:\nDonnerstahlbarren (5), Lebendiger Stahl (2), Geist der Harmonie (3)\n[q]Beim Schmieden dieser Waffe erlernt Ihr das Erschaffen der wiedergeborenen schwarzen Planaraxt.\nBeute von:\nItoka\nZone:\nInsel des Donners\n\n[q3]Die wiedergeborene Planaraxt\nWird beim Anlegen gebunden\nEinhändig Axt\n3 - 8 Schaden Geschwindigkeit 2.60\n(2.1 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 2.\nHaltbarkeit 90 / 90\n35"}
MultiLanguageSpellData['de'][138877] = {name = "[q3]Wiedergeborene Mondsichel", additional_info = "Wirken in 2.5 sek.\nTools: Schmiedehammer\nReagenzien:\nDonnerstahlbarren (5), Lebendiger Stahl (3), Geist der Harmonie (3)\n[q]Beim Schmieden dieser Waffe erlernt Ihr das Erschaffen des wiedergeborenen Mondspaltbeils.\nBeute von:\nItoka\nZone:\nInsel des Donners\n\n[q3]Wiedergeborene Mondsichel\nWird beim Anlegen gebunden\nZweihändig Axt\n7 - 15 Schaden Geschwindigkeit 3.60\n(3.1 Schaden pro Sekunde)\n+4 Stärke\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 100 / 100\n35"}
MultiLanguageSpellData['de'][138878] = {name = "[q4]Die wiedergeborene schwarze Planaraxt", additional_info = "Wirken in 2.5 sek.\nTools: Schmiedehammer\nReagenzien:\nDonnerstahlbarren (10), Lebendiger Stahl (4), Geist der Harmonie (6), Die wiedergeborene Planaraxt\n[q]Beim Schmieden dieser Waffe erlernt Ihr das Erschaffen der tückischen wiedergeborenen Schneide der Ebenen.\nBeruf:\nSchmiedekunst von Pandaria\nEntdeckung:\nDie wiedergeborene Planaraxt\n\n[q4]Die wiedergeborene schwarze Planaraxt\nWird beim Anlegen gebunden\nEinhändig Axt\n3 - 8 Schaden Geschwindigkeit 2.60\n(2.1 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 2.\nHaltbarkeit 110 / 110\n35"}
