MultiLanguageSpellData['de'][139771] = {name = "Blitzpeitsche", additional_info = "Unbegrenzte Reichweite\nWirken in 2 sek.\n[q]Trifft einen Gegner mit einem Blitzschlag, der auf einen Gegner in der Nähe überspringt. Der Zauber wirkt sich auf bis zu 5 Ziele aus und fügt jedem folgenden Ziel immer größeren Naturschaden zu."}
MultiLanguageSpellData['de'][139772] = {name = "Kosmischer Beschuss", additional_info = "{Kanalisiert (Wirken in} {1 sek.) 10 sek. Abklingzeit}\n[q]Kanalisiert einen kosmischen Beschuss."}
MultiLanguageSpellData['de'][139773] = {name = "Banner des Mantisreiches", additional_info = "Wirken in 2 sek.\n[q]Trotz der mächtigen Magie, über die sie verfügen, bevorzugen die Mogu zur Errichtung gewaltiger Denkmäler häufig den Einsatz von Sklaven. Dieses Kassenbuch dokumentiert den Sklavenverschleiß bei der Errichtung eines solchen Denkmals."}
MultiLanguageSpellData['de'][139774] = {name = "Kosmischer Beschuss", additional_info = nil}
MultiLanguageSpellData['de'][139775] = {name = "Banner des Mantisreiches", additional_info = nil}
MultiLanguageSpellData['de'][139776] = {name = "Banner des Mantisreiches", additional_info = "Wirken in 2 sek.\n[q]Obwohl die Mantis Windwolle und kaiserliche Seide verwenden, ist ihr bevorzugtes Material eine Art von \"Gewebe\", das aus den Flügeln verschiedener insektoider Kreaturen geschaffen wird - einschließlich ihrer eigenen. Dieses Banner ist ein Beispiel."}
MultiLanguageSpellData['de'][139777] = {name = "Steinschmettern", additional_info = "25 Meter Reichweite\nWirken in 3 sek.\nBenötigt Nahkampfwaffe\n[q]Ein heftiger Überkopfangriff, der körperlichen Schaden verursacht und alle Gegner vor dem Zaubernden betäubt."}
MultiLanguageSpellData['de'][139778] = {name = "Statue Frozen Slam Prep", additional_info = nil}
MultiLanguageSpellData['de'][139779] = {name = "Uralter Harzspender", additional_info = "Wirken in 2 sek.\n[q]Die Mantis bevorzugen es, das Kypariharz vor dem Verzehr reifen zu lassen. Dazu verwenden sie Vorrichtungen wie diese. An diesem uralten Exemplar könnt Ihr erkennen, dass sich ihr Entwurf im Laufe der Zeit nur unwesentlich verändert hat."}
MultiLanguageSpellData['de'][139780] = {name = "Die alte Gottesanbeterin", additional_info = "Wirken in 2 sek.\n[q]Diese Statue eines Klaxxi'va stammt in etwa aus der Zeit der Ankunft der Titanen. Um den Sockel der Statue ist ein Gebet an \"den Siebenköpfigen\" eingelassen. Das Wort \"Klaxxi\" bezeichnete in der alten Sprache einen Priester."}
MultiLanguageSpellData['de'][139781] = {name = "Inaktiver Schallsignalgeber", additional_info = "Wirken in 2 sek.\n[q]Die Technologie hinter den Schallsignalgebern der Mantis ist für alle anderen Völker undurchschaubar. Ihre Funktionalität scheint auf einem Teil der Mantisphysiologie zu beruhen. Dieses uralte Schallsignal ist – obwohl intakt – ohne einen Mantis als Anwender vollkommen unbrauchbar."}
MultiLanguageSpellData['de'][139782] = {name = "Überreste eines Getreuen", additional_info = "Wirken in 2 sek.\n[q]Wie es scheint, ist der Konservierungsprozess in Bern nicht ohne Risiko. Nur der Kopf dieses Getreuen hat dem Zahn der Zeit standgehalten. Er scheint aus einer Zeit vor der Revolution der Pandaren zu stammen, das genaue Zeitalter zu bestimmen ist jedoch unmöglich."}
MultiLanguageSpellData['de'][139783] = {name = "Mantislampe", additional_info = "Wirken in 2 sek.\n[q]Das Leuchten dieser Lampe wird weder durch Feuer noch Magie erzeugt. In ihrem Inneren könnt Ihr viele leuchtende Insekten erkennen, die in Bern konserviert wurden."}
MultiLanguageSpellData['de'][139784] = {name = "Pollensammler", additional_info = "Wirken in 2 sek.\n[q]Es ist schwierig, den Zweck dieses Objekts zu bestimmen, es scheint jedoch eine Art Pollensammler zu sein."}
MultiLanguageSpellData['de'][139785] = {name = "Kypariharzbehälter", additional_info = "Wirken in 2 sek.\n[q]Auch wenn es nach Bern aussieht, ist dieser Behälter in der Tat aus Kunchongsekret gefertigt. Das Gleiche gilt für viele herkömmliche Einrichtungsgegenstände der Mantis."}
MultiLanguageSpellData['de'][139786] = {name = "[q3]Himmelshäscher der Mantis", additional_info = "Wirken in 2 sek.\n[q]Dieses uralte \"Himmelshäscher\"-Schwert wurde für fliegende Mantis hergestellt: es ist extrem leicht und gut ausbalanciert, sodass es von einem herabstoßenden Angreifer leicht in weiten Bögen geschwungen werden kann. Die meisten Mantis werfen während ihres Übergangsritus in die Reihen der Erwachsenen ihre Flügel ab, als Zeichen stark genug zu sein um schwere Waffen und Rüstung zu tragen - daher ist es sehr selten, so feine Handwerkskunst in einer leichten Mantisklinge zu finden. Es ist wahrscheinlich, dass diese Waffe einst von einem Getreuen geführt wurde.\n[q3]Himmelshäscher der Mantis\n[q7]Wird an Kriegsmeute gebunden\nEinhändig Schwert\n4 - 8 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 90 / 90\n32\n[q]\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter 'Restaurierte Artefakte' protokolliert.\""}
MultiLanguageSpellData['de'][139787] = {name = "[q3]Schallimpulsgenerator", additional_info = "Wirken in 2 sek.\n[q]Die Mantis können in einem weitaus breiteren Spektrum Geräusche hören und erzeugen, als alle anderen sterblichen Völker. Ihr angeborenes Verständnis extrem hoher und niedriger Frequenzen gestattet es ihnen, Mantiswaffen wie diese zu erschaffen. Die Schallimpulse dieses Apparats können in der Tat Muskeln und anderes Gewebe auf zellularer Ebene zum Zerreißen bringen – direkte Treffer können die inneren Organe des Opfers verflüssigen.\n[q3]Schallimpulsgenerator\n[q7]Wird an Kriegsmeute gebunden\nDistanz Schusswaffe\n6 - 12 Schaden Geschwindigkeit 3.00\n(3.0 Schaden pro Sekunde)\n+4 Beweglichkeit\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 100 / 100\n32\n[q]\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter 'Restaurierte Artefakte' protokolliert.\""}
