MultiLanguageSpellData['de'][144359] = {name = "Gabe der Titanen", additional_info = "Sofort\n[q]Norushen verleiht Spielercharakteren Immunität gegen Stolz. Wenn sich alle Spielercharaktere mit 'Gabe der Titanen' innerhalb von 8 Metern aufhalten, erhalten sie außerdem 'Macht der Titanen'."}
