MultiLanguageSpellData['de'][145411] = {name = "Wutanfall", additional_info = "Nahkampfreichweite\nWirken in 1 sek.\n[q]Macht wütend. Hebt Bewegungseinschränkungs- und Kontrollverlusteffekte auf und macht dagegen immun. Erhöht die Bewegungsgeschwindigkeit um 100%, den verursachten Schaden um 150% und das Angriffstempo um 25%. Hält 10 Sek. lang an."}
