MultiLanguageSpellData['de'][145413] = {name = "Verstümmeln (Schildhand)", additional_info = "Nahkampfreichweite\nSofort\n[q]Greift sofort mit beiden Waffen an und verursacht (115% der Angriffskraft)% Waffenschaden mit jeder Waffe. Gewährt 2 Combopunkte."}
MultiLanguageSpellData['de'][145414] = {name = "Verstümmeln", additional_info = "Nahkampfreichweite\nSofort\n[q]Greift sofort mit beiden Waffen an und verursacht (115% der Angriffskraft)% Waffenschaden mit jeder Waffe. Gewährt 2 Combopunkte."}
MultiLanguageSpellData['de'][145415] = {name = "Verstümmeln", additional_info = "{55 Energie} {Nahkampfreichweite}\nSofort\n[q]Greift sofort mit beiden Waffen an und verursacht (115% der Angriffskraft)% Waffenschaden mit jeder Waffe. Gewährt 0 Combopunkt."}
MultiLanguageSpellData['de'][145416] = {name = "Vergiften", additional_info = "{35 Energie} {Nahkampfreichweite}\nSofort\n[q]Finishing-Move, der sofort Naturschaden proportional zu den auf dem Ziel bestehenden Combopunkten verursacht. Nach Einsatz von 'Vergiften' ist Eure Chance, das Ziel zu vergiften, um 15% erhöht. Dieser Effekt hält eine Sekunde plus jeweils eine weitere Sekunde pro Combopunkt lang an."}
MultiLanguageSpellData['de'][145417] = {name = "Blutung", additional_info = "{25 Energie} {Nahkampfreichweite}\nSofort\n[q]Finishing-Move, der Schaden im Lauf der Zeit verursacht. Hält pro Combopunkt länger an und verursacht mehr Schaden."}
MultiLanguageSpellData['de'][145418] = {name = "Zerhäckseln", additional_info = "{25 Energie} {100 Meter Reichweite}\nSofort\n[q]Finishing-Move, der alle Combopunkte eines nahen Ziels verbraucht, um Euer Nahkampfangriffstempo um 40% zu erhöhen. Hält pro Combopunkt länger an."}
MultiLanguageSpellData['de'][145419] = {name = "Tödliches Gift", additional_info = "100 Meter Reichweite\nSofort\n[q]Wenn Eure Waffen vergiftet sind, besteht eine Chance, dass Ihr Zielen, die bereits mit Eurem tödlichen Gift vergiftet sind, 200 Naturschaden zufügt."}
MultiLanguageSpellData['de'][145420] = {name = "Tödliches Gift", additional_info = "100 Meter Reichweite\nSofort\n[q]Überzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. [(11.374% der Angriffskraft) * 12 / 2] Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort (8.14% der Angriffskraft) Naturschaden."}
MultiLanguageSpellData['de'][145421] = {name = "Tödliches Gift", additional_info = "Wirken in 3 sek.\nBenötigt Einhändige Nahkampfwaffe\n[q]Überzieht Eure Waffen mit einem tödlichen Gift, das 12 Sek. lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. 1600 Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort 200 Naturschaden.\n(Procchance: 30%)"}
MultiLanguageSpellData['de'][145422] = {name = "Dolchfächer", additional_info = "35 Energie\nSofort\n[q]Wirbelt sofort herum und schleudert allen Zielen im Umkreis von 10 Metern einen Klingenregen entgegen, der 1005 körperlichen Schaden verursacht. Dieser Angriff hat eine Chance, Eure Ziele zu einer normalen Rate zu vergiften. Gewährt 1005 Combopunkte, wenn Ihr ein Ziel trefft, auf dem bereits Eure Combopunkte aktiv sind."}
MultiLanguageSpellData['de'][145423] = {name = "Verstohlenheit", additional_info = "{Sofort} {6 sek. Abklingzeit}\n[q]Verbirgt Euch in den Schatten, wodurch Ihr um Gegner herumschleichen könnt, ohne gesehen zu werden. Hält an, bis die Aktion abgebrochen wird."}
MultiLanguageSpellData['de'][145424] = {name = "Fieser Trick", additional_info = "{40 Energie} {10 Meter Reichweite}\nSofort\nBenötigt Verstohlenheit\n[q]Betäubt das Ziel 4 Sek. lang. Muss im Verstohlenheitsmodus sein. Gewährt 2 Combopunkt."}
MultiLanguageSpellData['de'][145425] = {name = "Schattenschritt", additional_info = "100 Meter Reichweite\nSofort\n[q]Lässt Euch in die Schatten tauchen, um hinter Eurem Ziel zu erscheinen und 2 Sek. lang eine um 70% erhöhte Bewegungsgeschwindigkeit zu erhalten. [ Täuschung : Wenn Ihr ' Schattenschritt ' bereits erlernt habt, erhaltet Ihr stattdessen 1 zusätzliche Aufladung ' Schattenschritt ' ]"}
MultiLanguageSpellData['de'][145426] = {name = "Schattenschritt", additional_info = "25 Meter Reichweite\n{Sofort} {24 sek. Abklingzeit}\n[q]Lässt Euch in die Schatten tauchen, um hinter dem Gegner zu erscheinen. Danach wird Eure Bewegungsgeschwindigkeit 2 Sek. lang um 70% erhöht."}
MultiLanguageSpellData['de'][145427] = {name = "Tritt", additional_info = "Nahkampfreichweite\n{Sofort} {15 sek. Abklingzeit}\n[q]Ein schneller Tritt, der das Wirken von Zaubern unterbricht und 2 Sek. lang verhindert, dass diese Art Zauber gewirkt werden kann."}
