MultiLanguageSpellData['de'][145434] = {name = "Arkanschlag", additional_info = "{8% von Grundmana} {40 Meter Reichweite}\nWirken in 2 sek.\n[q]Überzieht einen Gegner mit Energie und verursacht so (66.519% der Zaubermacht) Arkanschaden. Erzeugt eine Arkane Aufladung.\n\n Pro Arkaner Aufladung wird der Schaden von 'Arkanschlag' um 60 % und seine Manakosten um 90 % erhöht."}
MultiLanguageSpellData['de'][145435] = {name = "Arkane Geschosse", additional_info = "60 Meter Reichweite\nKanalisiert\n[q]Kann nur eingesetzt werden, wenn Ihr über 'Freizaubern' verfügt.\n\n Feuert im Verlauf von 2.5 Sek. fünf Wellen arkaner Geschosse auf den Gegner ab, die insgesamt [5 * (52.6% der Zaubermacht)] Arkanschaden verursachen."}
MultiLanguageSpellData['de'][145436] = {name = "Arkane Geschosse", additional_info = "40 Meter Reichweite\nKanalisiert (Wirken in 2 sek.)\n[q]Feuert im Verlauf von 2.5 Sek. fünf Wellen arkaner Geschosse auf den Gegner ab, die pro Welle (52.6% der Zaubermacht) Arkanschaden verursachen. Erzeugt eine Arkane Aufladung.\n\n Pro Arkaner Aufladung wird der Schaden von 'Arkane Geschosse' um 60 % erhöht."}
MultiLanguageSpellData['de'][145437] = {name = "Arkanbeschuss", additional_info = "{4% von Grundmana} {40 Meter Reichweite}\n{Sofort} {3 sek. Abklingzeit}\n[q]Schleudert mehrere Geschosse aus Arkanenergie auf das gegnerische Ziel, die 1006 Arkanschaden verursachen. Der Zauber trifft auch 4 zusätzliche Gegner in der Nähe und fügt ihnen 40% Schaden zu. Verbraucht alle Arkanen Aufladungen.\n\n Pro Arkaner Aufladung wird der Schaden von 'Arkanbeschuss' um 60 % erhöht."}
