MultiLanguageSpellData['de'][148270] = {name = "Glyphe 'Unbändiger Elementar'", additional_info = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nBeruf:\nInschriftenkunde (150)\nEntdeckung:\nForschung: Jadefeuertinte\n\nKlassen: Magier\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Wasserelementar wird durch einen unbändigen Wasserelementar ersetzt. Exklusiv mit: Glyphe 'Verdampfen' Glyphe 'Gezeiten' Glyphe 'Sturmwacht' Glyphe 'Finstere Tiefe' Glyphe 'Dampfende Wut' Glyphe 'Kältewellen'\n11"}
MultiLanguageSpellData['de'][148271] = {name = "Glyphe 'Verdampfen'", additional_info = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nBeruf:\nInschriftenkunde (100)\nEntdeckung:\nForschung: Löwentinte\n\nKlassen: Magier\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Größe Eures Wasserelementars um 15%. Exklusiv mit: Glyphe 'Unbändiger Elementar' Glyphe 'Gezeiten' Glyphe 'Sturmwacht' Glyphe 'Finstere Tiefe' Glyphe 'Dampfende Wut' Glyphe 'Kältewellen'\n11"}
