MultiLanguageSpellData['de'][156560] = {name = "[q3]Draenischer Stein der Weisen", additional_info = "Wirken in 3 sek.\nReagenzien:\nAlchemischer Katalysator (5), Echteisenerz\nVerkäufer:\nJoshua Alvarez\nZone:\nKriegsspeer\nKosten:\n1\n\n[q3]Draenischer Stein der Weisen\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n[q2]Anlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n35\nBenötigtAlchemie von Draenor\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\""}
MultiLanguageSpellData['de'][156561] = {name = "Draenisches Fläschchen der Beweglichkeit", additional_info = "Wirken in 2.5 sek.\nOhne Beruf:\nReagenzien:\nKristallphiole , Feuerwurz (4), Sternenblume (4)\nVerkäufer:\nJoshua Alvarez\nZone:\nKriegsspeer\nKosten:\n1\n\n[q2]Benutzen: Erhöht die Beweglichkeit 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n35"}
