MultiLanguageSpellData['de'][161353] = {name = "Verwandlung", additional_info = "{4% von Grundmana} {30 Meter Reichweite}\nWirken in 1.7 sek.\n[q]Verwandelt den Gegner in ein Eisbärenjunges, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]"}
MultiLanguageSpellData['de'][161354] = {name = "Verwandlung", additional_info = "{4% von Grundmana} {30 Meter Reichweite}\nWirken in 1.7 sek.\n[q]Verwandelt den Gegner in ein Äffchen, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]"}
