MultiLanguageSpellData['de'][161386] = {name = "Erlernen", additional_info = "Wirken in 3 sek.\n[q]Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Schmiede bauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Erzeugnissen der Schmiedekunst und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Schmiedekunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Schmiedemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig."}
MultiLanguageSpellData['de'][161387] = {name = "Erlernen", additional_info = "Wirken in 3 sek.\n[q]Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Alchemielabor bauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Erzeugnissen der Alchemie und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Alchemie', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Alchemiemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig."}
MultiLanguageSpellData['de'][161388] = {name = "Erlernen", additional_info = "Wirken in 3 sek.\n[q]Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Gerberei bauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Erzeugnissen der Lederverarbeitung und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Lederverarbeitung', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Lederverarbeitungsmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig."}
MultiLanguageSpellData['de'][161389] = {name = "Erlernen", additional_info = "Wirken in 3 sek.\n[q]Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Verzauberungsatelier bauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Gegenständen der Verzauberkunst und ermöglicht Charakteren ohne Verzauberfertigkeit, Gegenstände zu entzaubern. Gewährt außerdem Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Verzauberkunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Verzauberkunstmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig."}
MultiLanguageSpellData['de'][161390] = {name = "Erlernen", additional_info = "Wirken in 3 sek.\n[q]Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Maßschneiderei bauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Schneidereierzeugnissen und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Schneiderei', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Schneidereimissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig."}
MultiLanguageSpellData['de'][161391] = {name = "Erlernen", additional_info = "Wirken in 3 sek.\n[q]Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Schreibstube bauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Erzeugnissen der Inschriftenkunde und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Inschriftenkunde', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Inschriftenkundemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig."}
