MultiLanguageSpellData['de'][162209] = {name = "[q3]Mechanischer Axtschnabel", additional_info = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel\nOhne Beruf:\nReagenzien:\nGetriebefederteile (50)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\n[q3]Mechanischer Axtschnabel\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Beschwört Euren mechanischen Tukan oder gibt ihn wieder frei.\n1 - 80 ( 80)"}
MultiLanguageSpellData['de'][162210] = {name = "[q3]Lebensechter mechanischer Frosteber", additional_info = "Wirken in 3.5 sek.\nTools: Gyromatischer Mikroregler\nOhne Beruf:\nReagenzien:\nGetriebefederteile (50), Prächtiges Fell (40)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\n[q3]Lebensechter mechanischer Frosteber\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euren lebensechten mechanischen Eber beschwören oder wieder freigeben.\n1 - 80 ( 80)"}
MultiLanguageSpellData['de'][162214] = {name = "[q3]Persönliches Hologramm", additional_info = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nOhne Beruf:\nReagenzien:\nGetriebefederteile (50)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\n[q3]Persönliches Hologramm\nWird bei Benutzung gebunden\nSpielzeug\n[q2]Benutzen: Erstellt 1 Min. lang ein temporäres Hologramm von Euch selbst. (5 Min Abklingzeit)\n[q]\"Das Bild kann auf einige Emotes reagieren.\""}
MultiLanguageSpellData['de'][162216] = {name = "[q3]Wurmlochzentrifuge", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGetriebefederteile (50)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\n[q3]Wurmlochzentrifuge\nWird bei Benutzung gebunden\nSpielzeug\n[q2]Benutzen: Erschafft ein rotierendes Wurmloch, das der Ingenieur verwenden kann, um Draenor zu bereisen. (4 Std. Abklingzeit)\n34\nBenötigtIngenieurskunst von Draenor\n(1)"}
MultiLanguageSpellData['de'][162217] = {name = "[q3]Wechselblaster", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel\nOhne Beruf:\nReagenzien:\nGetriebefederteile (50), Temporaler Kristall\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\n[q3]Wechselblaster\nWird bei Benutzung gebunden\n[q2]Benutzen: Tauscht Eure Position mit der eines anderen Gruppenmitglieds. Kann nicht im Kampf genutzt werden. (1 Min Abklingzeit)\n[q]\"Achtung: Der Tausch mit einem Ziel, das einen neuralen Stummschalter verwendet, ist lebensgefährlich.\""}
MultiLanguageSpellData['de'][162218] = {name = "[q4]Blingtron 5000", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nGetriebefederteile (100)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\n[q4]Blingtron 5000\nWird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Setzt den verbesserten Blingtron 5000 zusammen, einen wilden, aber großzügigen Roboter. Einerseits lässt er Spielercharakteren einmal am Tag kleine Präsente zukommen, anderseits bekämpft er andere Blingtron-Einheiten bis zum Tode. (4 Std. Abklingzeit)\nBenötigtIngenieurskunst von Draenor\n(1)"}
