MultiLanguageSpellData['de'][162287] = {name = "Der lebende Berg", additional_info = "Sofort\n[q]Tectus kann nicht getötet werden, solange er unter der Wirkung von 'Der lebende Berg' steht.\n\n Er wird regelmäßig Energie regenerieren. Je mehr Gesundheit er verliert, umso schneller wird er regenerieren.\n\n Die Kraft von 'Lebender Berg' wird aufgezehrt, wenn Tectus 'Tektonische Unruhe' kanalisiert. Das macht ihn anfällig für 'Zertrümmern'."}
MultiLanguageSpellData['de'][162288] = {name = "Zuwachs", additional_info = "Sofort\n[q]Tectus absorbiert regelmäßig Erde in seinen Körper und erhöht damit den Schaden, den er verursacht, um 5%. Dieser Effekt ist stapelbar.\n\n Wenn Tectus Schaden zugefügt wird, entfernt dies Stapel von 'Zuwachs'."}
