MultiLanguageSpellData['de'][162510] = {name = "Tektonische Unruhe", additional_info = "Sofort\n[q]Tectus entlädt seine aufgestaute seismische Instabilität in die Erde und verursacht eine gewaltige Reihe von Erdbeben, die jeweils 1806 Naturschaden bei allen Spielercharakteren verursachen.\n\n Wenn Tectus' Gesundheit während der 'Tektonischen Unruhe' erschöpft wird, wird er zertrümmert."}
